  const parts = ["1", "2", "1", "2", "3", "7", "10", "20", "26", "0", "9"];
  const target = big ? 100000 : r.int(1, 14);
  let s = "";
  while (s.length < target) s += r.pick(big ? parts.filter(p => p !== "0") : parts);
  return [s.slice(0, target)];
}

