function countReadings(s: string): number {
  const MOD = 1_000_000_007;
  const go = (i: number): number => {
    if (i === s.length) return 1;
    if (s[i] === "0") return 0; // no piece may start with 0
    let total = go(i + 1);
    if (i + 1 < s.length && Number(s.slice(i, i + 2)) <= 26) total += go(i + 2);
    return total % MOD;
  };
  return go(0);
}

