function countReadings(s: string): number {
  const MOD = 1_000_000_007, n = s.length;
  const ways = new Array<number>(n + 1).fill(0);
  ways[0] = 1;
  for (let i = 1; i <= n; i++) {
    if (s[i - 1] !== "0") ways[i] = ways[i - 1];
    if (i >= 2) {
      const two = Number(s.slice(i - 2, i));
      if (two >= 10 && two <= 26) ways[i] = (ways[i] + ways[i - 2]) % MOD;
    }
  }
  return ways[n];
}

